package net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.DcrInitialAccessToken;
import net.civeira.phylax.feature.access.dcrinitialaccesstoken.domain.valueobject.MaxUsesVO;

class MaxUsesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of max uses of dcr initial access token")
  void test_max_uses_value_holder_assign_plain_value() {
    Object holder = new Object();
    MaxUsesValueHolder<Object> value = new MaxUsesValueHolder<>(holder);
    Assertions.assertSame(holder, value.maxUses(1), "Setters must return the holder");
    Assertions.assertTrue(value.getMaxUsesValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getMaxUses().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of max uses of dcr initial access token")
  void test_max_uses_value_holder_assign_value_object() {
    Object holder = new Object();
    MaxUsesValueHolder<Object> value = new MaxUsesValueHolder<>(holder);
    MaxUsesVO vo = MaxUsesVO.from(1);
    Assertions.assertFalse(value.getMaxUsesValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.maxUses(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getMaxUsesValue().orElseThrow());
    Assertions.assertSame(holder, value.maxUses(Optional.empty()));
    Assertions.assertFalse(value.getMaxUsesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.maxUses(Optional.of(vo)));
    Assertions.assertSame(vo, value.getMaxUsesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of max uses of dcr initial access token against the original")
  void test_max_uses_value_holder_read() {
    Object holder = new Object();
    MaxUsesValueHolder<Object> value = new MaxUsesValueHolder<>(holder);
    MaxUsesVO vo = MaxUsesVO.from(1);
    MaxUsesVO other = MaxUsesVO.from(1);
    DcrInitialAccessToken original = Mockito.mock(DcrInitialAccessToken.class);
    Mockito.when(original.getMaxUsesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readMaxUses(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readMaxUses(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.maxUses(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readMaxUses(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readMaxUses(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of max uses of dcr initial access token")
  void test_max_uses_value_holder_unset() {
    Object holder = new Object();
    MaxUsesValueHolder<Object> value = new MaxUsesValueHolder<>(holder);
    MaxUsesVO vo = MaxUsesVO.from(1);
    value.maxUses(vo);
    Assertions.assertSame(holder, value.unsetMaxUsesIfMatches("maxUses_other"));
    Assertions.assertTrue(value.getMaxUsesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetMaxUsesIfMatches("maxUses"));
    Assertions.assertFalse(value.getMaxUsesValue().isPresent(),
        "The field name must clear the value");
    value.maxUses(vo);
    Assertions.assertSame(holder, value.unsetMaxUses());
    Assertions.assertFalse(value.getMaxUsesValue().isPresent(), "Unset must clear the value");
  }
}
